<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<div class="ps-coa-history-categories"><p><?php esc_html_e( 'Laboratory Categories Reported', 'pepselect-coa-archive' ); ?></p><ul><?php foreach ( $report['qc_strip_rows'] as $row ) : $failed = 'fail' === $row['status']['value']; ?><li class="<?php echo $failed ? 'is-failed' : ( 'pass' === $row['status']['value'] ? 'is-success' : 'is-neutral' ); ?>"><span aria-hidden="true"><?php echo $failed ? '!' : ( 'pass' === $row['status']['value'] ? '✓' : '—' ); ?></span><strong><?php echo esc_html( $row['short_label'] ); ?></strong><small><?php echo esc_html( $row['reported'] ? $row['detail'] : '--' ); ?></small></li><?php endforeach; ?></ul></div>
